    #[test]
    fn other_compound_containers_are_not_misclassified_as_encrypted_ooxml() {
        let codec = XlsxCodec;
        for (label, stream_names) in [
            ("legacy workbook", &["Workbook"][..]),
            ("encryption info only", &["EncryptionInfo"][..]),
            ("encrypted package only", &["EncryptedPackage"][..]),
        ] {
            let input = encrypted_ooxml_fixture::compound_file_with_streams(stream_names);
            let error = codec
                .load(&input, CommonLoadOptions::default())
                .expect_err("non-OOXML compound input must not load as a workbook");
            assert_ne!(
                error.code,
                OmErrorCode::EncryptedWorkbookUnsupported,
                "{label}"
            );
        }

        let mut looping_directory =
            encrypted_ooxml_fixture::compound_file_with_streams(&[
                "EncryptionInfo",
                "EncryptedPackage",
            ]);
        let fat_offset = looping_directory.len() - 512;
        looping_directory[fat_offset..fat_offset + 4].copy_from_slice(&0_u32.to_le_bytes());
        let error = codec
            .load(&looping_directory, CommonLoadOptions::default())
            .expect_err("a looping CFB directory chain must not be classified");
        assert_ne!(
            error.code,
            OmErrorCode::EncryptedWorkbookUnsupported
        );

        let mut orphaned_streams =
            encrypted_ooxml_fixture::compound_file_with_streams(&[
                "EncryptionInfo",
                "EncryptedPackage",
            ]);
        orphaned_streams[512 + 76..512 + 80]
            .copy_from_slice(&0xffff_ffff_u32.to_le_bytes());
        let error = codec
            .load(&orphaned_streams, CommonLoadOptions::default())
            .expect_err("orphan encryption stream entries must not classify the container");
        assert_ne!(
            error.code,
            OmErrorCode::EncryptedWorkbookUnsupported
        );
    }

    #[test]
    fn signed_package_inventory_is_visible_and_clean_or_dirty_save_fails_closed() {
        let codec = XlsxCodec;
        let signed_bytes = signed_ooxml_fixture::package_with_fake_digital_signature(
            &synthetic_workbook_bytes(),
        );
        let mut loaded = codec
            .load(&signed_bytes, CommonLoadOptions::default())
            .expect("signed workbook remains readable");
        let inventory = loaded.digital_signature_inventory();

        assert!(inventory.has_artifacts());
        assert_eq!(
            inventory.part_uris(),
            &[
                "_xmlsignatures/_rels/origin.sigs.rels".to_string(),
                "_xmlsignatures/origin.sigs".to_string(),
                "_xmlsignatures/sig1.xml".to_string(),
            ]
        );
        assert_eq!(
            inventory.relationship_part_uris(),
            &[
                "_rels/.rels".to_string(),
                "_xmlsignatures/_rels/origin.sigs.rels".to_string(),
            ]
        );

        for label in ["clean", "dirty"] {
            if label == "dirty" {
                loaded.state.insert_cell(
                    SheetId(1),
                    1,
                    1,
                    CellData {
                        value: CellValue::Number(42.0),
                        formula: None,
                        style_id: None,
                    },
                );
            }
            let error = codec
                .save(&loaded, CommonSaveOptions::default())
                .expect_err("signed package rewrite must fail closed");
            assert_eq!(
                error.code,
                OmErrorCode::SignedPackageMutationUnsupported,
                "{label}"
            );
            assert_eq!(
                error.message,
                "XlsxCodec::save refuses to rewrite packages containing OPC digital-signature artifacts",
                "{label}"
            );
        }

        loaded.package =
            OpcPackage::from_bytes(&synthetic_workbook_bytes()).expect("unsigned replacement");
        let error = codec
            .save(&loaded, CommonSaveOptions::default())
            .expect_err("manual package replacement must not bypass source signature policy");
        assert_eq!(
            error.code,
            OmErrorCode::SignedPackageMutationUnsupported
        );

        let mut unsigned = codec
            .load(
                synthetic_workbook_bytes().as_slice(),
                CommonLoadOptions::default(),
            )
            .expect("load unsigned workbook");
        unsigned
            .package
            .add_part(OpcPart {
                name: "_xmlsignatures/late-artifact.bin".to_string(),
                content_type: None,
                compression: CompressionMethod::Stored,
                bytes: vec![1, 2, 3],
            })
            .expect("add current-package signature artifact");
        let error = codec
            .save(&unsigned, CommonSaveOptions::default())
            .expect_err("current package signature artifacts must be re-scanned");
        assert_eq!(
            error.code,
            OmErrorCode::SignedPackageMutationUnsupported
        );
    }

