    #[test]
    fn parses_workbook_defined_names_into_model_table() {
        let workbook = parse_workbook(
            br#"<?xml version="1.0" encoding="UTF-8"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"
 xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheets>
    <sheet name="Sheet1" sheetId="1" r:id="rId1"/>
    <sheet name="Sheet2" sheetId="2" r:id="rId2"/>
  </sheets>
  <definedNames>
    <definedName name="GlobalTotal" hidden="1" function="1" functionGroupId="14" shortcutKey="G" comment="kept">Sheet1!$A$1</definedName>
    <definedName name="_xlnm.Print_Area" localSheetId="1">Sheet2!$A:$D</definedName>
  </definedNames>
</workbook>"#,
            &BTreeMap::new(),
            OoxmlDialect::Transitional,
        )
        .expect("workbook defined names");

        assert!(!workbook.defined_names.is_dirty());
        let global = workbook
            .defined_names
            .lookup_in_scope(NameScope::Workbook, "globaltotal")
            .expect("global defined name");
        assert_eq!(global.refers_to.text, "Sheet1!$A$1");
        assert!(global.metadata.hidden);
        assert!(global.metadata.function);
        assert_eq!(global.metadata.function_group_id, Some(14));
        assert_eq!(global.metadata.shortcut_key.as_deref(), Some("G"));
        assert_eq!(global.metadata.comment.as_deref(), Some("kept"));

        let local = workbook
            .defined_names
            .lookup_in_scope(NameScope::Worksheet(SheetId(2)), "_XLNM.PRINT_AREA")
            .expect("sheet defined name");
        assert_eq!(local.refers_to.text, "Sheet2!$A:$D");
        assert_eq!(local.scope, NameScope::Worksheet(SheetId(2)));
    }

    #[test]
    fn load_and_clean_save_preserve_defined_names() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_bytes()).expect("package");
        let workbook_xml = std::str::from_utf8(
            package
                .part("xl/workbook.xml")
                .expect("workbook xml")
                .bytes
                .as_slice(),
        )
        .expect("workbook xml utf8")
        .replace(
            "</sheets>",
            r#"</sheets><definedNames><definedName name="GlobalTotal" hidden="1">Sheet1!$A$1</definedName></definedNames>"#,
        );
        package
            .replace_part_bytes("xl/workbook.xml", workbook_xml.into_bytes())
            .expect("replace workbook xml");
        let bytes = package.to_bytes().expect("package bytes");

        let loaded = codec
            .load(bytes.as_slice(), CommonLoadOptions::default())
            .expect("load workbook");
        let loaded_name = loaded
            .state
            .lookup_name(None, "globaltotal")
            .expect("loaded defined name");
        assert_eq!(loaded_name.refers_to.text, "Sheet1!$A$1");
        assert!(loaded_name.metadata.hidden);
        assert!(!loaded.state.defined_names.is_dirty());

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(saved.as_slice()).expect("saved package");
        let saved_workbook_xml = std::str::from_utf8(
            saved_package
                .part("xl/workbook.xml")
                .expect("saved workbook xml")
                .bytes
                .as_slice(),
        )
        .expect("saved workbook xml utf8");
        assert!(
            saved_workbook_xml.contains(
                r#"<definedName name="GlobalTotal" hidden="1">Sheet1!$A$1</definedName>"#
            )
        );
    }

    #[test]
    fn load_inventories_drawingless_chartsheet_host_and_clean_save_validates_it() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&synthetic_workbook_bytes()).expect("package");
        let workbook_rels_xml = std::str::from_utf8(
            package
                .part(WORKBOOK_RELS_PART_NAME)
                .expect("workbook rels")
                .bytes
                .as_slice(),
        )
        .expect("workbook rels utf8")
        .replace(
            r#"Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml""#,
            r#"Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chartsheet" Target="chartsheets/sheet1.xml""#,
        );
        package
            .replace_part_bytes(WORKBOOK_RELS_PART_NAME, workbook_rels_xml.into_bytes())
            .expect("replace workbook rels");
        let chartsheet_xml = br#"<?xml version="1.0" encoding="UTF-8"?><chartsheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"/>"#.to_vec();
        package
            .add_part(OpcPart {
                name: "xl/chartsheets/sheet1.xml".to_string(),
                content_type: None,
                compression: CompressionMethod::Stored,
                bytes: chartsheet_xml.clone(),
            })
            .expect("add chartsheet part");
        let bytes = package.to_bytes().expect("package bytes");

        let loaded = codec
            .load(bytes.as_slice(), CommonLoadOptions::default())
            .expect("load workbook with chartsheet");

        assert_eq!(loaded.state.worksheets[0].kind, SheetKind::ChartSheet);
        assert_eq!(
            loaded.state.worksheets[0].part_uri.as_deref(),
            Some("xl/chartsheets/sheet1.xml")
        );
        assert!(
            loaded
                .state
                .worksheet_data
                .get(&loaded.state.worksheets[0].id)
                .expect("chartsheet data placeholder")
                .cells
                .is_empty()
        );
        assert!(
            !loaded
                .state
                .worksheet_data
                .get(&loaded.state.worksheets[0].id)
                .expect("chartsheet data placeholder")
                .source_xml
                .is_empty()
        );
        let sheet_id = loaded.state.worksheets[0].id;
        let drawing_support = loaded
            .sheet_drawing_support_parts
            .get(&sheet_id)
            .expect("drawingless chartsheet host inventory");
        assert_eq!(
            drawing_support.sheet_part_uri.as_deref(),
            Some("xl/chartsheets/sheet1.xml")
        );
        assert_eq!(
            drawing_support.sheet_part_source_bytes.as_deref(),
            Some(chartsheet_xml.as_slice())
        );
        assert!(drawing_support.is_empty());

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save drawingless chartsheet");
        let saved_package = OpcPackage::from_bytes(saved.as_slice()).expect("saved package");
        assert_eq!(
            saved_package
                .part("xl/chartsheets/sheet1.xml")
                .expect("saved chartsheet host")
                .bytes,
            chartsheet_xml
        );

        let mut host_missing = loaded.clone();
        assert!(
            host_missing
                .package
                .remove_part("xl/chartsheets/sheet1.xml")
        );
        let error = codec
            .save(&host_missing, office_common::SaveOptions::default())
            .expect_err("save should reject missing drawingless chartsheet host");
        assert!(
            error
                .to_string()
                .contains("explicit drawing host sheet part is missing: xl/chartsheets/sheet1.xml"),
            "{error}"
        );

        let mut host_changed = loaded.clone();
        host_changed
            .package
            .replace_part_bytes(
                "xl/chartsheets/sheet1.xml",
                br#"<?xml version="1.0" encoding="UTF-8"?><chartsheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr/></chartsheet>"#.to_vec(),
            )
            .expect("replace drawingless chartsheet host");
        let error = codec
            .save(&host_changed, office_common::SaveOptions::default())
            .expect_err("save should reject changed drawingless chartsheet host");
        assert!(
            error.to_string().contains(
                "explicit drawing host sheet part bytes changed: xl/chartsheets/sheet1.xml"
            ),
            "{error}"
        );
    }

