    #[test]
    fn strip_calc_chain_relationships_removes_matches_by_type_or_target() {
        let rels_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
  <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/calcChain" Target="calcChain.xml"><ext preserve="1"/></Relationship>
  <Relationship Id="rId3" Type="https://example.com/relationships/opaque" Target="./calcChain.xml"/>
  <Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>"#;

        let stripped = String::from_utf8(
            super::strip_calc_chain_relationships(rels_xml)
                .expect("strip calc chain relationships"),
        )
        .expect("relationships xml utf8");

        assert!(stripped.contains(r#"Id="rId1""#));
        assert!(stripped.contains(r#"Target="worksheets/sheet1.xml""#));
        assert!(stripped.contains(r#"Id="rId4""#));
        assert!(stripped.contains(r#"Target="styles.xml""#));
        assert!(!stripped.contains(r#"Id="rId2""#));
        assert!(!stripped.contains(r#"Id="rId3""#));
        assert!(!stripped.contains("calcChain.xml"));
    }

