    #[test]
    fn strip_calc_chain_relationships_preserves_unrelated_structure() {
        let rels_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships" data-root="keep">
  <ext preserve="1"/>
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml" data-sheet="keep"><ext preserve="sheet"/></Relationship>
  <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/calcChain" Target="calcChain.xml"><ext preserve="drop"/></Relationship>
  <Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml" data-style="keep"/>
</Relationships>"#;

        let stripped = String::from_utf8(
            super::strip_calc_chain_relationships(rels_xml)
                .expect("strip calc chain relationships"),
        )
        .expect("relationships xml utf8");

        assert!(stripped.contains(r#"data-root="keep""#));
        assert!(stripped.contains(r#"<ext preserve="1"/>"#));
        assert!(stripped.contains(r#"Id="rId1""#));
        assert!(stripped.contains(r#"data-sheet="keep""#));
        assert!(stripped.contains(r#"<ext preserve="sheet"/>"#));
        assert!(stripped.contains(r#"Id="rId3""#));
        assert!(stripped.contains(r#"data-style="keep""#));
        assert!(!stripped.contains(r#"Id="rId2""#));
        assert!(!stripped.contains("calcChain.xml"));
        assert!(!stripped.contains(r#"preserve="drop""#));
    }

    #[test]
    fn strip_calc_chain_content_type_override_removes_calc_chain_entries() {
        let content_types_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="xl/calcChain.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.calcChain+xml"><ext preserve="1"/></Override>
  <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
</Types>"#;

        let stripped = String::from_utf8(
            super::strip_calc_chain_content_type_override(content_types_xml)
                .expect("strip calc chain content type override"),
        )
        .expect("content types xml utf8");

        assert!(stripped.contains("/xl/workbook.xml"));
        assert!(stripped.contains("/xl/worksheets/sheet1.xml"));
        assert!(!stripped.contains("calcChain.xml"));
    }

    #[test]
    fn strip_calc_chain_content_type_override_preserves_unrelated_structure() {
        let content_types_xml = br#"<?xml version="1.0" encoding="UTF-8"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types" data-root="keep">
  <ext preserve="1"/>
  <Default Extension="xml" ContentType="application/xml" data-default="keep"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml" data-workbook="keep"/>
  <Override PartName="/xl/calcChain.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.calcChain+xml"><ext preserve="drop"/></Override>
  <Override PartName="/xl/charts/style1.xml" ContentType="application/vnd.ms-office.chartstyle+xml" data-style="keep"/>
</Types>"#;

        let stripped = String::from_utf8(
            super::strip_calc_chain_content_type_override(content_types_xml)
                .expect("strip calc chain content type override"),
        )
        .expect("content types xml utf8");

        assert!(stripped.contains(r#"data-root="keep""#));
        assert!(stripped.contains(r#"<ext preserve="1"/>"#));
        assert!(stripped.contains(r#"data-default="keep""#));
        assert!(stripped.contains(r#"data-workbook="keep""#));
        assert!(stripped.contains(r#"/xl/charts/style1.xml"#));
        assert!(stripped.contains(r#"data-style="keep""#));
        assert!(!stripped.contains("calcChain.xml"));
        assert!(!stripped.contains(r#"preserve="drop""#));
    }

    #[test]
    fn invalidate_calc_chain_artifacts_removes_calc_chain_part_and_metadata() {
        let mut package =
            OpcPackage::from_bytes(&workbook_with_hyperlink_comment_and_calc_chain_bytes())
                .expect("base workbook package");

        super::invalidate_calc_chain_artifacts(
            &mut package,
            "xl/workbook.xml",
            "xl/_rels/workbook.xml.rels",
            Some("xl/calcChain.xml"),
        )
        .expect("invalidate calc chain artifacts");

        assert!(!package.contains("xl/calcChain.xml"));
        assert!(package.contains("xl/comments1.xml"));
        assert!(package.contains("xl/drawings/vmlDrawing1.vml"));

        let workbook_rels = String::from_utf8(
            package
                .part("xl/_rels/workbook.xml.rels")
                .expect("workbook rels")
                .bytes
                .clone(),
        )
        .expect("workbook rels utf8");
        assert!(workbook_rels.contains(r#"Id="rId1""#));
        assert!(!workbook_rels.contains("calcChain"));

        let content_types = String::from_utf8(
            package
                .part("[Content_Types].xml")
                .expect("content types")
                .bytes
                .clone(),
        )
        .expect("content types utf8");
        assert!(content_types.contains("/xl/workbook.xml"));
        assert!(!content_types.contains("/xl/calcChain.xml"));
    }

    #[test]
    fn rewrite_worksheet_xml_rejects_missing_source_xml() {
        let worksheet = WorksheetData {
            cells: BTreeMap::new(),
            source_xml: Vec::new(),
            dirty: true,
            dirty_cells: BTreeSet::new(),
            ..WorksheetData::default()
        };

        let error = rewrite_worksheet_xml(
            &worksheet,
            None,
            "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
        )
            .expect_err("rewrite should fail when worksheet source xml is missing");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(error.message.contains("worksheet source xml is missing"));
    }

