    fn stylesheet_xml_string_from_workbook_bytes(workbook_bytes: &[u8]) -> String {
        String::from_utf8(
            OpcPackage::from_bytes(workbook_bytes)
                .expect("workbook package")
                .part("xl/styles.xml")
                .expect("styles part")
                .bytes
                .clone(),
        )
        .expect("styles xml utf8")
    }

