    #[test]
    fn normalize_relationship_target_resolves_relative_and_absolute_paths() {
        assert_eq!(
            super::normalize_relationship_target("../comments1.xml", &["xl", "worksheets"]),
            Some("xl/comments1.xml".to_string())
        );
        assert_eq!(
            super::normalize_relationship_target("./drawings/../media/image1.png", &["xl"]),
            Some("xl/media/image1.png".to_string())
        );
        assert_eq!(
            super::normalize_relationship_target("/xl/theme/theme1.xml", &["xl", "worksheets"]),
            Some("xl/theme/theme1.xml".to_string())
        );
    }

    #[test]
    fn normalize_relationship_target_rejects_package_root_escape() {
        assert_eq!(
            super::normalize_relationship_target("../../comments1.xml", &["xl"]),
            None
        );
    }

    #[test]
    fn parse_relationship_entries_rejects_invalid_internal_targets() {
        for target in [
            "../../comments1.xml",
            "%2e%2e/%2E%2E/comments1.xml",
            "worksheets\\sheet1.xml",
            "worksheets/%2Fsheet1.xml",
            "worksheets/%GG.xml",
            "worksheets/sheet1.xml#fragment",
            "worksheets/sheet1.xml?query",
            "https://example.com/internal.xml",
        ] {
            let rels_xml = format!(
                r#"<?xml version="1.0" encoding="UTF-8"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="{target}"/>
</Relationships>"#,
            );
            let error = super::parse_relationship_entries(rels_xml.as_bytes(), &["xl"])
                .expect_err("invalid internal relationship target must fail");

            assert_eq!(error.code, OmErrorCode::Parse);
        }
    }

    #[test]
    fn normalize_relationship_target_returns_none_for_empty_result() {
        assert_eq!(
            super::normalize_relationship_target("../../..", &["xl"]),
            None
        );
        assert_eq!(super::normalize_relationship_target("/", &["xl"]), None);
    }

