    #[test]
    fn parse_worksheet_hyperlink_refs_propagates_missing_ref_error() {
        let worksheet_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"
 xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <hyperlinks>
    <hyperlink r:id="rId1"/>
  </hyperlinks>
</worksheet>"#;

        let error = super::parse_worksheet_hyperlink_refs(worksheet_xml.as_bytes())
            .expect_err("parse should fail when worksheet hyperlink ref is missing");

        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(
            error
                .message
                .contains("worksheet <hyperlink> is missing required ref")
        );
    }

