    #[test]
    fn parse_comment_part_summary_rejects_non_numeric_author_id() {
        let comments_xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<comments xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <authors><author>Codex</author></authors>
  <commentList>
    <comment ref="A1" authorId="bogus"><text><t>Bad author</t></text></comment>
  </commentList>
</comments>"#;

        let error = super::parse_comment_part_summary(comments_xml.as_bytes())
            .expect_err("parse should fail when authorId is non-numeric");

        assert_eq!(error.code, OmErrorCode::Parse);
        assert!(error.message.contains("invalid digit found in string"));
    }

