        assert!(!styles_summary.cell_xfs[1].apply_fill);
        assert!(styles_summary.cell_xfs[2].apply_number_format);
        assert_eq!(styles_summary.cell_xfs[3].fill_id, 1);
        assert!(styles_summary.cell_xfs[3].apply_fill);
