    #[test]
    fn load_collects_color_scheme_nested_child_before_parent_in_theme_summary() {
        let codec = XlsxCodec;
        let mut package =
            OpcPackage::from_bytes(&workbook_with_theme_color_scheme_value_children_bytes())
                .expect("base workbook package");
        let theme_xml = String::from_utf8(
            package
                .part("xl/theme/theme1.xml")
                .expect("theme part")
                .bytes
                .clone(),
        )
        .expect("theme xml utf8")
        .replace(
            r#"      <a:dk1><a:sysClr val="windowText" lastClr="000000"/></a:dk1>"#,
            "      <a:sysClr val=\"windowText\" lastClr=\"000000\"/>\n      <a:dk1/>",
        );
        package
            .replace_part_bytes("xl/theme/theme1.xml", theme_xml.into_bytes())
            .expect("replace theme part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let theme_summary = loaded
            .support_parts
            .theme_summaries
            .get("xl/theme/theme1.xml")
            .expect("typed theme summary");

        assert_eq!(
            theme_summary.color_scheme_child_names,
            vec!["sysClr".to_string(), "dk1".to_string(), "lt1".to_string()]
        );
        assert_eq!(
            theme_summary.color_scheme_child_nested_names,
            vec![
                Vec::<String>::new(),
                Vec::<String>::new(),
                vec!["srgbClr".to_string()],
            ]
        );
        assert_eq!(
            theme_summary.color_scheme_child_nested_attr_maps,
            vec![
                Vec::<BTreeMap<String, String>>::new(),
                Vec::<BTreeMap<String, String>>::new(),
                vec![BTreeMap::from([("val".to_string(), "FFFFFF".to_string())])],
            ]
        );
    }

