    #[test]
    fn load_collects_extension_list_instead_of_colors_in_styles_summary() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&workbook_with_stylesheet_colors_children_bytes())
            .expect("base workbook package");
        let styles_xml = String::from_utf8(
            package
                .part("xl/styles.xml")
                .expect("styles part")
                .bytes
                .clone(),
        )
        .expect("styles xml utf8")
        .replace("<colors><indexedColors/><mruColors/></colors>", "<extLst/>");
        package
            .replace_part_bytes("xl/styles.xml", styles_xml.into_bytes())
            .expect("replace styles part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let styles_summary = loaded
            .support_parts
            .styles_summary
            .as_ref()
            .expect("typed styles summary");

        assert_eq!(
            styles_summary.root_child_names,
            vec![
                "fonts".to_string(),
                "fills".to_string(),
                "borders".to_string(),
                "cellStyleXfs".to_string(),
                "cellStyles".to_string(),
                "cellXfs".to_string(),
                "extLst".to_string(),
                "tableStyles".to_string(),
            ]
        );
        assert!(styles_summary.has_extension_list);
        assert!(!styles_summary.has_colors);
        assert!(!styles_summary.has_dxfs);
        assert!(styles_summary.has_table_styles_count_attr);
        assert!(styles_summary.table_styles.is_some());
    }

