    #[test]
    fn load_collects_cell_style_xf_explicit_false_number_format_and_fill_flags_in_styles_summary() {
        let codec = XlsxCodec;
        let mut package = OpcPackage::from_bytes(&workbook_with_cell_style_xf_apply_flags_bytes())
            .expect("base workbook package");
        let styles_xml = String::from_utf8(
            package
                .part("xl/styles.xml")
                .expect("styles part")
                .bytes
                .clone(),
        )
        .expect("styles xml utf8")
        .replace(
            r#"<cellStyleXfs count="1"><xf numFmtId="14" fontId="0" fillId="1" borderId="0" applyNumberFormat="1" applyFill="1"/></cellStyleXfs>"#,
            r#"<cellStyleXfs count="2"><xf numFmtId="14" fontId="0" fillId="1" borderId="0" applyNumberFormat="0" applyFill="1"/><xf numFmtId="14" fontId="0" fillId="1" borderId="0" applyNumberFormat="1" applyFill="0"/></cellStyleXfs>"#,
        );
        package
            .replace_part_bytes("xl/styles.xml", styles_xml.into_bytes())
            .expect("replace styles part");
        let loaded = codec
            .load(
                &package.to_bytes().expect("package bytes"),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let styles_summary = loaded
            .support_parts
            .styles_summary
            .as_ref()
            .expect("typed styles summary");

        assert!(!styles_summary.cell_style_xfs[0].apply_number_format);
        assert!(styles_summary.cell_style_xfs[0].apply_fill);
        assert!(styles_summary.cell_style_xfs[1].apply_number_format);
        assert!(!styles_summary.cell_style_xfs[1].apply_fill);
    }

