    #[test]
    fn load_collects_worksheet_relationships_part_summary() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_blank_comment_anchor_and_relationship_root_attrs_extra_relationship_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let worksheet_support = loaded
            .worksheet_support_parts
            .get(&sheet_id)
            .expect("worksheet support parts");
        let relationships_summary = worksheet_support
            .relationships_summary
            .as_ref()
            .expect("worksheet relationships summary");

        assert_eq!(relationships_summary.root_name, "Relationships");
        assert_eq!(
            relationships_summary.root_attr_map,
            BTreeMap::from([
                ("data-layout".to_string(), "preserve".to_string()),
                ("data-root".to_string(), "alpha".to_string()),
                (
                    "xmlns".to_string(),
                    "http://schemas.openxmlformats.org/package/2006/relationships".to_string(),
                ),
            ])
        );
        assert_eq!(
            relationships_summary.root_child_names,
            vec![
                "Relationship".to_string(),
                "Relationship".to_string(),
                "Relationship".to_string(),
                "Relationship".to_string(),
            ]
        );
        assert!(relationships_summary.root_extra_child_xmls.is_empty());
        assert_eq!(
            relationships_summary.relationship_ids,
            vec![
                "rId9".to_string(),
                "rId1".to_string(),
                "rId3".to_string(),
                "rId2".to_string(),
            ]
        );
        assert_eq!(
            relationships_summary.relationship_attr_maps,
            vec![
                BTreeMap::from([
                    ("Id".to_string(), "rId9".to_string()),
                    (
                        "Target".to_string(),
                        "https://opaque.example/preserve".to_string()
                    ),
                    ("TargetMode".to_string(), "External".to_string()),
                    (
                        "Type".to_string(),
                        "https://example.com/relationships/opaque".to_string()
                    ),
                    ("data-extra".to_string(), "1".to_string()),
                ]),
                BTreeMap::from([
                    ("Id".to_string(), "rId1".to_string()),
                    ("Target".to_string(), "https://example.com".to_string()),
                    ("TargetMode".to_string(), "External".to_string()),
                    ("Type".to_string(), HYPERLINK_RELATIONSHIP_TYPE.to_string()),
                ]),
                BTreeMap::from([
                    ("Id".to_string(), "rId3".to_string()),
                    ("Target".to_string(), "xl/comments1.xml".to_string()),
                    ("Type".to_string(), COMMENTS_RELATIONSHIP_TYPE.to_string()),
                    ("data-order".to_string(), "comments".to_string()),
                ]),
                BTreeMap::from([
                    ("Id".to_string(), "rId2".to_string()),
                    (
                        "Target".to_string(),
                        "xl/drawings/vmlDrawing1.vml".to_string()
                    ),
                    (
                        "Type".to_string(),
                        VML_DRAWING_RELATIONSHIP_TYPE.to_string()
                    ),
                    ("data-order".to_string(), "vml".to_string()),
                ]),
            ]
        );
        assert_eq!(
            relationships_summary.relationship_inner_xmls,
            vec![String::new(), String::new(), String::new(), String::new(),]
        );
        assert!(worksheet_support.hyperlink_summaries.is_empty());
        assert!(worksheet_support.hyperlink_refs.is_empty());
        assert!(worksheet_support.hyperlink_bindings.is_empty());
        assert_eq!(
            worksheet_support.legacy_drawing_relationships,
            vec![WorksheetRelationshipBinding {
                relationship_id: "rId2".to_string(),
                target: "xl/drawings/vmlDrawing1.vml".to_string(),
            }]
        );
        assert_eq!(
            worksheet_support.comment_relationships,
            vec![WorksheetRelationshipBinding {
                relationship_id: "rId3".to_string(),
                target: "xl/comments1.xml".to_string(),
            }]
        );
    }

