    #[test]
    fn load_collects_comment_root_attrs_container_attrs_and_extra_xml_in_worksheet_support_parts() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_comment_root_attrs_and_extra_child_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let worksheet_support = loaded
            .worksheet_support_parts
            .get(&sheet_id)
            .expect("worksheet support parts");
        let comment_summary = worksheet_support
            .comment_summaries
            .get("xl/comments1.xml")
            .expect("comment summary");

        assert_eq!(comment_summary.root_name, "comments");
        assert_eq!(
            comment_summary
                .root_attr_map
                .get("data-root")
                .map(String::as_str),
            Some("alpha")
        );
        assert_eq!(
            comment_summary.root_child_names,
            vec![
                "authors".to_string(),
                "extLst".to_string(),
                "commentList".to_string(),
            ]
        );
        assert_eq!(
            comment_summary.root_extra_child_xmls,
            vec![
                r#"<extLst><ext uri="urn:comment"><payload preserved="true"/></ext></extLst>"#
                    .to_string()
            ]
        );
        assert_eq!(
            comment_summary.authors_attr_map,
            Some(BTreeMap::from([("preserve".to_string(), "1".to_string())]))
        );
        assert_eq!(
            comment_summary.comment_list_attr_map,
            Some(BTreeMap::from([("count".to_string(), "1".to_string())]))
        );
        assert_eq!(
            comment_summary.authors,
            vec!["Codex".to_string(), "OpenAI".to_string()]
        );
        assert_eq!(
            comment_summary.comments,
            vec![WorksheetCommentSummary {
                reference: "A1".to_string(),
                author_id: Some(1),
                attr_map: BTreeMap::from([
                    ("authorId".to_string(), "1".to_string()),
                    ("ref".to_string(), "A1".to_string()),
                ]),
                text: "Preserve me".to_string(),
                text_xml: Some(r#"<t>Preserve me</t>"#.to_string()),
            }]
        );
    }

