    #[test]
    fn load_collects_worksheet_hyperlinks_part_summary() {
        let codec = XlsxCodec;
        let loaded = codec
            .load(
                &workbook_with_hyperlinks_container_attrs_and_extra_attr_bytes(),
                CommonLoadOptions::default(),
            )
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let worksheet_support = loaded
            .worksheet_support_parts
            .get(&sheet_id)
            .expect("worksheet support parts");
        let hyperlinks_part_summary = worksheet_support
            .hyperlinks_part_summary
            .as_ref()
            .expect("worksheet hyperlinks part summary");

        assert_eq!(hyperlinks_part_summary.root_name, "hyperlinks");
        assert_eq!(
            hyperlinks_part_summary.root_attr_map,
            BTreeMap::from([
                ("data-layout".to_string(), "preserve".to_string()),
                ("data-root".to_string(), "alpha".to_string()),
            ])
        );
        assert_eq!(
            hyperlinks_part_summary.root_child_names,
            vec!["hyperlink".to_string(), "hyperlink".to_string()]
        );
        assert!(hyperlinks_part_summary.root_extra_child_xmls.is_empty());
        assert_eq!(
            hyperlinks_part_summary.hyperlink_attr_maps,
            vec![
                BTreeMap::from([
                    ("data-extra".to_string(), "1".to_string()),
                    ("display".to_string(), "Example".to_string()),
                    ("r:id".to_string(), "rId1".to_string()),
                    ("ref".to_string(), "A1".to_string()),
                    ("tooltip".to_string(), "Visit example".to_string()),
                ]),
                BTreeMap::from([
                    ("data-kind".to_string(), "internal".to_string()),
                    ("display".to_string(), "Jump".to_string()),
                    ("location".to_string(), "Sheet1!A1".to_string()),
                    ("ref".to_string(), "B1".to_string()),
                    ("tooltip".to_string(), "Internal jump".to_string()),
                ]),
            ]
        );
        assert_eq!(
            hyperlinks_part_summary.hyperlink_inner_xmls,
            vec![String::new(), String::new()]
        );
    }

