    #[test]
    fn rewrite_materializes_anchor_placeholder_from_absolute_hyperlink_summary_without_legacy_refs()
    {
        let mut dirty_cells = BTreeSet::new();
        dirty_cells.insert((3, 3));
        let worksheet = WorksheetData {
            cells: BTreeMap::new(),
            source_xml: br#"<?xml version="1.0" encoding="UTF-8"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <sheetData/>
</worksheet>"#
                .to_vec(),
            dirty: true,
            dirty_cells,
            ..WorksheetData::default()
        };
        let support_parts = WorksheetSupportParts {
            worksheet_part_uri: Some("xl/worksheets/sheet1.xml".to_string()),
            relationships_part_uri: None,
            relationships_part_source_bytes: None,
            relationships_summary: None,
            hyperlinks_part_summary: None,
            comment_part_uris: Vec::new(),
            comment_anchor_refs: BTreeMap::new(),
            comment_part_source_bytes: BTreeMap::new(),
            comment_summaries: BTreeMap::new(),
            vml_drawing_part_uris: Vec::new(),
            vml_drawing_part_source_bytes: BTreeMap::new(),
            vml_drawing_summaries: BTreeMap::new(),
            hyperlink_summaries: vec![WorksheetHyperlinkSummary {
                reference: "$A$1:$C$3".to_string(),
                relationship_id: Some("rId1".to_string()),
                location: None,
                display: Some("Absolute".to_string()),
                tooltip: None,
            }],
            hyperlink_refs: Vec::new(),
            hyperlink_bindings: Vec::new(),
            hyperlink_relationship_ids: vec!["rId1".to_string()],
            legacy_drawing_relationships: Vec::new(),
            legacy_drawing_relationship_ids: Vec::new(),
            legacy_drawing_summaries: Vec::new(),
            comment_relationships: Vec::new(),
            comment_relationship_ids: Vec::new(),
        };

        let rewritten = rewrite_worksheet_xml(
            &worksheet,
            Some(&support_parts),
            "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
        )
        .expect("rewrite worksheet");
        let rewritten_xml = String::from_utf8(rewritten).expect("rewritten xml utf8");

        assert!(rewritten_xml.contains(r#"<dimension ref="A1:C3"/>"#));
        assert!(rewritten_xml.contains(r#"<row r="3"><c r="C3"/></row>"#));
    }

