    #[test]
    fn dirty_save_restores_comment_root_attrs_and_extra_children_for_blank_comment_anchor_without_hyperlink_summary_or_legacy_ref_lists()
     {
        let codec = XlsxCodec;
        let input = workbook_with_blank_comment_root_attrs_and_extra_child_bytes();
        let original_package = OpcPackage::from_bytes(&input).expect("original package");
        let original_comments = original_package
            .part("xl/comments1.xml")
            .expect("original comments part")
            .bytes
            .clone();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let worksheet_support = loaded
            .worksheet_support_parts
            .get_mut(&sheet_id)
            .expect("worksheet support parts");
        worksheet_support.comment_anchor_refs.clear();
        let comments_xml = String::from_utf8(
            loaded
                .package
                .part("xl/comments1.xml")
                .expect("comments part")
                .bytes
                .clone(),
        )
        .expect("comments xml utf8")
        .replace(r#"data-root="alpha""#, r#"data-root="beta""#)
        .replace(r#"<authors preserve="1">"#, r#"<authors preserve="2">"#)
        .replace(r#"uri="urn:comment""#, r#"uri="urn:changed""#);
        loaded
            .package
            .replace_part_bytes("xl/comments1.xml", comments_xml.into_bytes())
            .expect("replace comments part");
        loaded.state.insert_cell(
            sheet_id,
            3,
            3,
            CellData {
                value: CellValue::Number(4.0),
                formula: None,
                style_id: None,
            },
        );
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 3, 3),
                &office_common::OmArray::scalar(office_common::OmValue::Empty),
            )
            .expect("blank C3");
        assert!(loaded.state.cell(sheet_id, 3, 3).is_none());

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");

        assert_eq!(
            saved_package
                .part("xl/comments1.xml")
                .expect("saved comments part")
                .bytes,
            original_comments
        );
    }

