    #[test]
    fn save_rejects_explicit_worksheet_vml_shape_attr_drift() {
        let codec = XlsxCodec;
        let input = workbook_with_vml_shape_attrs_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let vml_xml = String::from_utf8(
            loaded
                .package
                .part("xl/drawings/vmlDrawing1.vml")
                .expect("vml drawing")
                .bytes
                .clone(),
        )
        .expect("vml utf8")
        .replace("position:absolute", "position:relative");
        loaded
            .package
            .replace_part_bytes("xl/drawings/vmlDrawing1.vml", vml_xml.into_bytes())
            .expect("replace vml drawing");

        let error = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect_err("save should fail when VML shape attrs drift");
        assert_eq!(error.code, OmErrorCode::InvalidState);
        assert!(
            error
                .message
                .contains("explicit worksheet VML drawing semantics changed")
        );
        assert!(error.message.contains("xl/drawings/vmlDrawing1.vml"));
    }

