    #[test]
    fn dirty_save_preserves_dimension_for_blank_hyperlink_comment_anchor() {
        let codec = XlsxCodec;
        let input = workbook_with_blank_hyperlink_comment_anchor_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 2, 2),
                &office_common::OmArray::scalar(office_common::OmValue::Number(9.0)),
            )
            .expect("set B2");

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let sheet_xml = String::from_utf8(
            saved_package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8");
        let comments_xml = String::from_utf8(
            saved_package
                .part("xl/comments1.xml")
                .expect("comments part")
                .bytes
                .clone(),
        )
        .expect("comments xml utf8");

        assert!(sheet_xml.contains(r#"<dimension ref="B1:C3"/>"#));
        assert!(sheet_xml.contains(r#"<hyperlink ref="C3" r:id="rId1"/>"#));
        assert!(comments_xml.contains(r#"ref="C3""#));
    }

