    #[test]
    fn dirty_save_restores_worksheet_hyperlinks_part_summary_for_blank_external_hyperlink_anchor_without_legacy_ref_lists()
     {
        let codec = XlsxCodec;
        let input =
            workbook_with_blank_external_hyperlink_anchor_and_hyperlinks_container_attrs_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let expected_summary = loaded
            .worksheet_support_parts
            .get(&sheet_id)
            .and_then(|worksheet_support| worksheet_support.hyperlinks_part_summary.clone())
            .expect("worksheet hyperlinks part summary");
        let worksheet_support = loaded
            .worksheet_support_parts
            .get_mut(&sheet_id)
            .expect("worksheet support parts");
        worksheet_support.hyperlink_refs.clear();
        let sheet_xml = String::from_utf8(
            loaded
                .package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8")
        .replace(r#"data-root="alpha""#, r#"data-root="beta""#)
        .replace(r#"data-extra="1""#, r#"data-extra="2""#)
        .replace(r#"r:id="rId1""#, r#"r:id="rId9""#)
        .replace(r#"display="Example""#, r#"display="Drifted""#)
        .replace(r#"tooltip="Visit example""#, r#"tooltip="Drifted tip""#);
        loaded
            .package
            .replace_part_bytes("xl/worksheets/sheet1.xml", sheet_xml.into_bytes())
            .expect("replace sheet xml");
        loaded.state.insert_cell(
            sheet_id,
            3,
            3,
            CellData {
                value: CellValue::Number(4.0),
                formula: None,
                style_id: None,
            },
        );
        loaded
            .state
            .set_range_values(
                &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 3, 3),
                &office_common::OmArray::scalar(office_common::OmValue::Empty),
            )
            .expect("blank C3");
        assert!(loaded.state.cell(sheet_id, 3, 3).is_none());

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let saved_sheet_xml_bytes = saved_package
            .part("xl/worksheets/sheet1.xml")
            .expect("saved sheet part")
            .bytes
            .as_slice();
        let saved_sheet_xml =
            String::from_utf8(saved_sheet_xml_bytes.to_vec()).expect("saved sheet xml utf8");
        let saved_summary = crate::parse_worksheet_hyperlinks_part_summary(saved_sheet_xml_bytes)
            .expect("saved worksheet hyperlinks summary")
            .expect("saved hyperlinks part summary");

        assert_eq!(saved_summary, expected_summary);
        assert!(saved_sheet_xml.contains(r#"data-root="alpha""#));
        assert!(saved_sheet_xml.contains(r#"data-layout="preserve""#));
        assert!(saved_sheet_xml.contains(r#"data-extra="1""#));
        assert!(saved_sheet_xml.contains(r#"r:id="rId1""#));
        assert!(saved_sheet_xml.contains(r#"display="Example""#));
        assert!(saved_sheet_xml.contains(r#"tooltip="Visit example""#));
        assert!(!saved_sheet_xml.contains(r#"data-root="beta""#));
        assert!(!saved_sheet_xml.contains(r#"data-extra="2""#));
        assert!(!saved_sheet_xml.contains(r#"r:id="rId9""#));
        assert!(!saved_sheet_xml.contains(r#"display="Drifted""#));
        assert!(!saved_sheet_xml.contains(r#"tooltip="Drifted tip""#));
    }

