    #[test]
    fn dirty_save_inserts_multiple_anchor_placeholders_in_segment_order_without_legacy_ref_lists() {
        let codec = XlsxCodec;
        let input =
            workbook_with_sparse_blank_hyperlink_comment_anchors_and_row_opaque_payload_bytes();
        let mut loaded = codec
            .load(&input, CommonLoadOptions::default())
            .expect("load workbook");
        let sheet_id = loaded.state.worksheets[0].id;
        let worksheet_support = loaded
            .worksheet_support_parts
            .get_mut(&sheet_id)
            .expect("worksheet support parts");
        worksheet_support.hyperlink_refs.clear();
        worksheet_support.comment_anchor_refs.clear();

        for col in [2, 4] {
            loaded.state.insert_cell(
                sheet_id,
                1,
                col,
                CellData {
                    value: CellValue::Number(f64::from(col)),
                    formula: None,
                    style_id: None,
                },
            );
            loaded
                .state
                .set_range_values(
                    &office_common::RangeRef::single_cell(WorkbookId(0), sheet_id, 1, col),
                    &office_common::OmArray::scalar(office_common::OmValue::Empty),
                )
                .expect("blank anchor cell");
            assert!(loaded.state.cell(sheet_id, 1, col).is_none());
        }

        let saved = codec
            .save(&loaded, office_common::SaveOptions::default())
            .expect("save workbook");
        let saved_package = OpcPackage::from_bytes(&saved).expect("saved package");
        let sheet_xml = String::from_utf8(
            saved_package
                .part("xl/worksheets/sheet1.xml")
                .expect("sheet part")
                .bytes
                .clone(),
        )
        .expect("sheet xml utf8");
        let comments_xml = String::from_utf8(
            saved_package
                .part("xl/comments1.xml")
                .expect("comments part")
                .bytes
                .clone(),
        )
        .expect("comments xml utf8");

        let a1_start = sheet_xml.find(r#"<c r="A1"><v>1</v></c>"#).expect("A1");
        let b1_start = sheet_xml.find(r#"<c r="B1"/>"#).expect("B1");
        let c1_start = sheet_xml.find(r#"<c r="C1"><v>3</v></c>"#).expect("C1");
        let d1_start = sheet_xml.find(r#"<c r="D1"/>"#).expect("D1");
        let opaque_start = sheet_xml
            .find(r#"<extLst><ext uri="urn:row"><payload preserved="true"/></ext></extLst>"#)
            .expect("row opaque");
        assert!(a1_start < b1_start);
        assert!(b1_start < c1_start);
        assert!(c1_start < d1_start);
        assert!(d1_start < opaque_start);
        assert!(sheet_xml.contains(r#"<hyperlink ref="B1" r:id="rId1"/>"#));
        assert!(sheet_xml.contains(r#"<hyperlink ref="D1" r:id="rId1"/>"#));
        assert!(comments_xml.contains(r#"ref="B1""#));
        assert!(comments_xml.contains(r#"ref="D1""#));

        let reopened = codec
            .load(&saved, CommonLoadOptions::default())
            .expect("reopen workbook");
        let reopened_sheet_id = reopened.state.worksheets[0].id;
        assert!(reopened.state.cell(reopened_sheet_id, 1, 2).is_none());
        assert!(reopened.state.cell(reopened_sheet_id, 1, 4).is_none());
    }

